// WITHOUT IoC - your code controls creation
public class OrderController {
    private final OrderService orderService;

    public OrderController() {
        // You manually create and wire everything
        var emailService = new EmailService();
        var orderRepo = new OrderRepository();
        this.orderService = new OrderService(orderRepo, emailService);
    }
}

// WITH IoC - Spring controls creation
@RestController
public class OrderController {
    private final OrderService orderService;

    // Just declare what you need - Spring handles creation
    public OrderController(OrderService orderService) {
        this.orderService = orderService;
    }
}

@Service
class OrderService {
    private final OrderRepository orderRepository;
    private final EmailService emailService;

    // Spring automatically injects these dependencies
    public OrderService(OrderRepository repo, EmailService email) {
        this.orderRepository = repo;
        this.emailService = email;
    }
}

@Service
public class DataSyncService {
    private final ApiClient apiClient;
    private final NotificationService notificationService;
    private ScheduledExecutorService scheduler;

    // Step 1: Constructor called - dependencies NOT yet injected
    public DataSyncService(ApiClient apiClient, 
                           NotificationService notificationService) {
        this.apiClient = apiClient;
        this.notificationService = notificationService;
        // Don't use injected fields here - they're null at this point
    }

    // Step 2: After injection completes, this runs
    @PostConstruct
    public void initialize() {
        // Safe to use injected dependencies now
        this.scheduler = Executors.newScheduledThreadPool(1);
        scheduler.scheduleAtFixedRate(
            this::syncData, 0, 5, TimeUnit.MINUTES
        );
        notificationService.sendStartupAlert("DataSync initialized");
    }

    // Step 3: Before container shutdown, cleanup resources
    @PreDestroy
    public void cleanup() {
        scheduler.shutdown();
        notificationService.sendShutdownAlert("DataSync stopped");
    }

    private void syncData() {
        apiClient.fetchUpdates();
    }
}

// TIGHT COUPLING - UserService creates its dependencies
class UserServiceTight {
    private final EmailService emailService;

    public UserServiceTight() {
        // Hardcoded to concrete EmailService
        this.emailService = new EmailService();
    }

    public void registerUser(String email) {
        // Now stuck with email notifications forever
        emailService.send(email, "Welcome!");
    }
}

// LOOSE COUPLING - UserService receives dependencies
interface NotificationService {
    void send(String recipient, String message);
}

@Service
class UserService {
    private final NotificationService notificationService;

    // Depends on interface, not concrete class
    public UserService(NotificationService notificationService) {
        this.notificationService = notificationService;
    }

    public void registerUser(String recipient) {
        // Works with any NotificationService implementation
        notificationService.send(recipient, "Welcome!");
    }
}

// Easily swap implementations without changing UserService
@Service
class EmailService implements NotificationService { /* ... */ }

@Service
class SmsService implements NotificationService { /* ... */ }

// Method 1: Inject ApplicationContext directly
@Service
public class EventPublisherService {
    private final ApplicationContext context;

    public EventPublisherService(ApplicationContext context) {
        this.context = context;
    }

    public void notifyOrderPlaced(Long orderId) {
        var event = new OrderPlacedEvent(this, orderId);
        context.publishEvent(event);  // Legitimate use
    }
}

// Method 2: Implement ApplicationContextAware
@Component
public class DynamicBeanRegistry implements ApplicationContextAware {
    private ApplicationContext context;

    @Override
    public void setApplicationContext(ApplicationContext ctx) {
        this.context = ctx;  // Spring calls this during init
    }

    public String getEnvironmentProperty(String key) {
        return context.getEnvironment().getProperty(key);
    }
}

// ANTI-PATTERN: Don't do this
public void processOrder() {
    // Bad: Using ApplicationContext as service locator
    var orderService = context.getBean(OrderService.class);
    orderService.process();  // Should inject OrderService instead
}

// Method 1: Stereotype annotations - auto-detected by component scan
@Service  // Makes this class a Spring bean
public class OrderService {
    private final OrderRepository repository;

    public OrderService(OrderRepository repository) {
        this.repository = repository;  // repository is also a bean
    }
}

@Repository  // Another stereotype annotation
public class OrderRepository {
    // Spring manages this object's lifecycle
}

// Method 2: @Bean method in @Configuration class
@Configuration
public class AppConfig {

    @Bean  // Spring calls this method and registers returned object as bean
    public RestTemplate restTemplate() {
        return new RestTemplate();  // Now RestTemplate is a bean
    }
}

// NOT a Spring bean - regular Java object
public class OrderCalculator {
    public double calculateTotal(List<Item> items) {
        // This is just a POJO, not managed by Spring
        return items.stream().mapToDouble(Item::getPrice).sum();
    }
}

var calculator = new OrderCalculator();  // You manage this, not Spring
